package io.github.mhaberler.adsbdongle.rtlsdr;

import static org.junit.Assert.assertEquals;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

/** Parity with webapp/src/modes-demod-2400.ts on the shared fixture (generated by webapp/src/fixtures/synth-iq.ts). */
public class ModeSDemod2400Test {
    private static final Path FIXTURES = Paths.get("../../../webapp/src/fixtures");

    private static List<String> expected() throws Exception {
        return Arrays.asList(
            new String(Files.readAllBytes(FIXTURES.resolve("adsb-2400.txt")), StandardCharsets.UTF_8).trim().split("\n"));
    }

    @Test
    public void fixtureMatchesTypeScript() throws Exception {
        byte[] iq = Files.readAllBytes(FIXTURES.resolve("adsb-2400.u8"));
        assertEquals(expected(), new ModeSDemod2400().push(iq, iq.length));
    }

    @Test
    public void fixtureSplitAcrossBuffers() throws Exception {
        byte[] iq = Files.readAllBytes(FIXTURES.resolve("adsb-2400.u8"));
        ModeSDemod2400 d = new ModeSDemod2400();
        List<String> got = new ArrayList<>();
        for (int o = 0; o < iq.length; o += 1234) {
            byte[] chunk = Arrays.copyOfRange(iq, o, Math.min(iq.length, o + 1234));
            got.addAll(d.push(chunk, chunk.length));
        }
        assertEquals(expected(), got);
    }
}
